CREATE POLICY "Company can read own logos" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'company-logos' AND (storage.foldername(name))[1] = public.current_company_id());
CREATE POLICY "Company can upload own logos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'company-logos' AND (storage.foldername(name))[1] = public.current_company_id());
CREATE POLICY "Company can update own logos" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'company-logos' AND (storage.foldername(name))[1] = public.current_company_id()) WITH CHECK (bucket_id = 'company-logos' AND (storage.foldername(name))[1] = public.current_company_id());
CREATE POLICY "Company can delete own logos" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'company-logos' AND (storage.foldername(name))[1] = public.current_company_id());